import{newGame,legal,apply,choose,score,met,focus,cost,CHANNELS,ROLES,PLOTS,invariant}from'./engine.js';import{board}from'./board.js';
const $=id=>document.getElementById(id),cards=await(await fetch('./cards.json')).json();let s,view,control='bots',revealed=false,auto=false,frameChoice=0;const styles=['builder','raider','conservative','framer','opportunist','explorer'];const colors=['#b84b32','#b28b24','#376a95'];const quotes=['Temporary relief. Permanent paperwork.','Independence, subject to renewal.','The exception has its own department.','Confidence is our most renewable product.','Transparency requires clearance.','A bridge to the next set of conditions.'];
function save(){localStorage.setItem('handshake-r07',JSON.stringify({s,control}))}function human(i){if(s.solo&&i===1)return false;return control==='humans'||(control==='bots'&&i===0)}function actor(){return s.pending?.kind==='reaction'?s.pending.owner:s.active}function button(text,fn,cls=''){let b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b}function select(items,on){let e=document.createElement('select');items.forEach((x,i)=>{let o=document.createElement('option');o.value=i;o.textContent=x;e.append(o)});e.onchange=()=>on(+e.value);return e}function act(a){let previous=actor();s=apply(s,a);invariant(s);save();revealed=false;render();if(control==='humans'&&!s.done&&actor()!==previous){$('handoffTitle').textContent='Pass to '+s.players[actor()].name;$('handoff').showModal()}}
function labelAction(a){if(a.type==='frame')return (a.move.kind==='rotate'?s.dice[a.move.index].id+(a.move.delta>0?' +1':' −1'):a.move.kind==='swap'?'Swap '+s.dice[a.move.i].id+' / '+s.dice[a.move.j].id:'Shift '+(a.move.delta<0?'left':'right'))+' → '+s.cards[s.market[a.index]].title;return(a.type==='audit'?'Suspend ':a.type==='poach'||a.type==='broker'?'Poach ':'Recruit ')+(a.id?s.cards[a.id].title:s.cards[s.market[a.index]]?.title||'')+(a.replace?' · return '+s.cards[a.replace].title:'')}
function actionGroup(title,actions){if(!actions.length)return;let box=document.createElement('div'),h=document.createElement('h3');h.textContent=title;box.append(h);let idx=0;box.append(select(actions.map(labelAction),i=>idx=i));box.append(button('Confirm '+title.toLowerCase(),()=>act(actions[idx])));$('actions').append(box)}
function render(){let p=s.players[actor()],active=s.players[s.active],actions=legal(s);$('round').textContent='ROUND '+s.round+' / 8';$('event').textContent=s.event===0?'PUBLIC HEARING':'EXPEDITED FUNDING';$('focus').textContent=s.mode==='window'?'Free recruitment: market slots '+(s.window+1)+' & '+(s.window+2):focus(s)===null?'Contested — every recruit costs 1 Favor':CHANNELS[focus(s)]+' is in focus · matching recruitment is free';$('seats').replaceChildren(...s.players.map((p,i)=>{let d=document.createElement('div');d.className='seat'+(i===s.active?' active':'');d.textContent=p.name+' · '+score(s,i)+' pts · '+p.favor+' Favor';return d}));$('turn').innerHTML='<span class="eyebrow">'+(s.pending?.kind==='reaction'?'ONE RESPONSE':s.done?'MEETING ADJOURNED':'YOUR TURN')+'</span><h2>'+p.name+'</h2>';$('agenda').textContent=p.role<0?'The System · public-state builder · no agenda or Plot':ROLES[p.role][0]+' · +2: '+ROLES[p.role][1];$('actions').replaceChildren();if(s.done){let order=s.players.map((p,i)=>({i,v:score(s,i),f:p.favor})).sort((a,b)=>b.v-a.v||b.f-a.f),w=order.filter(x=>x.v===order[0].v&&x.f===order[0].f);let msg=s.solo?(score(s,0)>score(s,1)||(score(s,0)===score(s,1)&&s.players[0].favor>s.players[1].favor)?'You win. The minutes will reflect that.':'The System wins. No irregularities were found.'):'Winner'+(w.length>1?'s':'')+': '+w.map(x=>s.players[x.i].name).join(' & ');$('actions').textContent=msg;$('actions').append(button('Another meeting',()=>$('setup').showModal()));auto=false}else if(!human(actor())){$('actions').append(button('Let '+p.name+' act · '+p.policy,()=>act(choose(s,p.policy)),'primary'));$('actions').append(button(auto?'Pause demonstration':'Run computer turns',()=>{auto=!auto;render()}))}else if(s.pending?.kind==='reaction'){let d=document.createElement('p');d.textContent=active.name+' wants '+s.cards[s.pending.id].title+'.';$('actions').append(d);actions.forEach(a=>$('actions').append(button(a.type==='veto'?'Veto · pay '+s.vetoCost+' Favor':'Allow transfer',()=>act(a),a.type==='veto'?'primary':'')))}else{if(s.pending)$('actions').append(document.createTextNode('Vetoed. Recruit an affordable fallback or hold.'));actionGroup('Recruit',actions.filter(a=>a.type==='recruit'));actionGroup('Poach · 1 Favor',actions.filter(a=>a.type==='poach'));if(p.plot){if(!revealed)$('actions').append(button('Reveal my Plot',()=>{revealed=true;render()}));else{let h=document.createElement('h3');h.textContent=PLOTS[p.plot.type];$('actions').append(h);actionGroup('Plot',actions.filter(a=>['audit','broker','bailout','frame'].includes(a.type)));let d=actions.find(a=>a.type==='discard');if(d)$('actions').append(button('Discard Plot & draw · uses turn',()=>act(d)))}}let pass=actions.find(a=>a.type==='pass');if(pass)$('actions').append(button('Hold position',()=>act(pass)))}
$('market').replaceChildren(...s.market.map((id,i)=>{let c=s.cards[id],d=document.createElement('article');d.className='card';d.style.setProperty('--c',colors[c.supply]);d.innerHTML='<span class="cost">'+cost(s,i)+' FAVOR</span><div class="tag">'+c.sphere.split(',')[0]+'</div><h3>'+c.title+'</h3><div class="flow">SUPPLIES '+CHANNELS[c.supply]+'<br>NEEDS '+CHANNELS[c.need]+'</div><div class="quote">“'+c.claim+'”<br><small>'+c.incentive+'</small></div>';return d}));$('networks').replaceChildren(...s.players.map((p,i)=>{let d=document.createElement('div');d.className='network';d.innerHTML='<h3>'+p.name+' · '+score(s,i)+' points</h3>';let row=document.createElement('div');row.className='minirow';for(let id of p.net){let c=s.cards[id],m=document.createElement('div');m.className='mini'+(s.suspended.includes(id)?' suspended':'');m.style.setProperty('--c',colors[c.supply]);let suppliers=p.net.filter(j=>j!==id&&!s.suspended.includes(j)&&s.cards[j].supply===c.need);m.innerHTML=c.title+'<small>'+CHANNELS[c.supply]+' → needs '+CHANNELS[c.need]+'</small><small>'+(s.suspended.includes(id)?'SUSPENDED · 0 points':met(s,i,id)?'✓ supplied by '+suppliers.map(j=>s.cards[j].title).join(', '):'○ unmet need · exposed')+'</small>';row.append(m)}if(!p.net.length)row.textContent='No institutions controlled yet.';d.append(row);return d}));$('log').replaceChildren(...s.log.slice(-12).reverse().map(x=>{let li=document.createElement('li');li.textContent=x;return li}));view?.update(s);if(auto&&!s.done&&!human(actor()))setTimeout(()=>{if(auto&&!s.done&&!human(actor()))act(choose(s,s.players[actor()].policy))},450)}
$('start').onsubmit=e=>{e.preventDefault();control=$('control').value;s=newGame(cards,{count:+$('count').value,mode:$('mode').value,seed:+$('seed').value,policies:styles});auto=control==='demo';save();$('setup').close();render()};$('new').onclick=()=>{auto=false;$('setup').showModal()};$('resume').onclick=()=>$('setup').close();$('rules').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();$('ready').onclick=()=>$('handoff').close();$('camera').onclick=()=>view?.toggle();try{let old=JSON.parse(localStorage.getItem('handshake-r07'));if(old?.s.version===7){invariant(old.s);s=old.s;s.cards=Object.fromEntries(cards.map(c=>[c.id,c]));control=old.control}}catch{}if(!s){s=newGame(cards);$('setup').showModal()}render();try{view=await board($('scene'));view.update(s)}catch(e){$('scene').textContent='3D view unavailable. All game actions remain available below.';console.error(e)}
